function toBeautyTest(definition) {
	const questions = definition.prompts.map(([question, ...choices], index) => ({
		id: `${definition.slug}-${index + 1}`,
		question,
		answers: choices.map(([label, profile], answerIndex) => ({
			value: `${index + 1}-${answerIndex + 1}`,
			label,
			scores: profile === "neutral" ? {} : { [profile]: 1 }
		}))
	}));
	return {
		slug: definition.slug,
		title: definition.title,
		description: definition.description,
		questions,
		getResult(answers) {
			const scores = {};
			questions.forEach((question) => {
				const selected = question.answers.find((answer) => answer.value === answers[question.id]);
				for (const [key, value] of Object.entries(selected?.scores ?? {})) scores[key] = (scores[key] ?? 0) + value;
			});
			const profile = Object.keys(definition.results).reduce((winner, candidate) => (scores[candidate] ?? 0) > (scores[winner] ?? 0) ? candidate : winner, definition.defaultProfile);
			return definition.results[profile] ?? definition.results[definition.defaultProfile];
		}
	};
}
