function buildTest(def) {
	const questions = def.prompts.map(([question, ...choices], index) => ({
		id: `${def.slug}-q${index + 1}`,
		question,
		answers: choices.map(([label, profile], option) => ({
			value: `${index + 1}-${option + 1}`,
			label,
			scores: { [profile]: 1 }
		}))
	}));
	return {
		slug: def.slug,
		title: def.title,
		description: def.description,
		questions,
		getResult(answers) {
			const totals = {};
			for (const question of questions) {
				const choice = question.answers.find((item) => item.value === answers[question.id]);
				for (const [profile, score] of Object.entries(choice?.scores ?? {})) totals[profile] = (totals[profile] ?? 0) + score;
			}
			const winner = Object.keys(def.outcomes).reduce((best, profile) => (totals[profile] ?? 0) > (totals[best] ?? 0) ? profile : best, def.defaultProfile);
			const [title, description, tips, link, linkLabel, note] = def.outcomes[winner];
			return {
				title,
				description,
				tips: [...tips],
				link,
				linkLabel,
				note
			};
		}
	};
}
