/** Results are a weighted preference match, not a medical or colour-analysis diagnosis.
* The first and second questions have extra weight because they define the main task. */
function createTest(def) {
	const questions = def.questions.map(([question, ...options], index) => ({
		id: `${def.slug}-${index + 1}`,
		question,
		answers: options.map(([label, profile], choiceIndex) => ({
			value: `${index + 1}-${choiceIndex + 1}`,
			label,
			scores: { [profile]: index < 2 ? 2 : 1 }
		}))
	}));
	return {
		slug: def.slug,
		title: def.title,
		description: def.description,
		questions,
		getResult(answers) {
			const totals = {
				a: 0,
				b: 0,
				c: 0,
				d: 0
			};
			questions.forEach((question) => {
				const answer = question.answers.find((item) => item.value === answers[question.id]);
				Object.entries(answer?.scores ?? {}).forEach(([key, points]) => {
					totals[key] += points;
				});
			});
			const strongest = Math.max(...Object.values(totals));
			const leaders = Object.keys(totals).filter((key) => totals[key] === strongest);
			const first = questions[0].answers.find((item) => item.value === answers[questions[0].id]);
			const primary = Object.keys(first?.scores ?? {})[0] ?? "a";
			const winner = leaders.includes(primary) ? primary : leaders[0];
			const outcome = def.outcomes[winner];
			return {
				...outcome,
				tips: [...outcome.tips]
			};
		}
	};
}
