function getSeo(pathname) {
	const path = normalizePath(pathname);
	return {
		...getSeoData(path),
		canonical: `${ORIGIN}${path}`
	};
}
function setMeta(selector, attribute, key, content) {
	let el = document.head.querySelector(selector);
	if (!el) {
		el = document.createElement("meta");
		el.setAttribute(attribute, key);
		document.head.appendChild(el);
	}
	el.setAttribute("content", content);
}
function setCanonical(url) {
	let link = document.head.querySelector("link[rel=\"canonical\"]");
	if (!link) {
		link = document.createElement("link");
		link.rel = "canonical";
		document.head.appendChild(link);
	}
	link.href = url;
}
function SEO() {
	const location = useLocation();
	useEffect(() => {
		const { title, description, keywords, canonical, robots } = getSeo(location.pathname);
		document.title = title;
		document.documentElement.lang = "ru";
		setMeta("meta[name=\"description\"]", "name", "description", description);
		setMeta("meta[name=\"robots\"]", "name", "robots", robots);
		if (keywords) setMeta("meta[name=\"keywords\"]", "name", "keywords", keywords);
		else document.head.querySelector("meta[name=\"keywords\"]")?.remove();
		setCanonical(canonical);
		setMeta("meta[property=\"og:type\"]", "property", "og:type", "website");
		setMeta("meta[property=\"og:site_name\"]", "property", "og:site_name", SITE_NAME);
		setMeta("meta[property=\"og:locale\"]", "property", "og:locale", "ru_RU");
		setMeta("meta[property=\"og:title\"]", "property", "og:title", title);
		setMeta("meta[property=\"og:description\"]", "property", "og:description", description);
		setMeta("meta[property=\"og:url\"]", "property", "og:url", canonical);
		setMeta("meta[name=\"twitter:card\"]", "name", "twitter:card", "summary_large_image");
		setMeta("meta[name=\"twitter:title\"]", "name", "twitter:title", title);
		setMeta("meta[name=\"twitter:description\"]", "name", "twitter:description", description);
	}, [location.pathname]);
	return null;
}
